struct sock *sk_alloc(struct net *net, int family,
                      gfp_t priority,
                      struct proto *prot)
{
  struct sock *sk;

  sk = sk_prot_alloc(prot, priority | __GFP_ZERO, family);
  if (sk) {
    sock_init_data(NULL, sk);
    sk->sk_family = family;
  }
  return sk;
}

